CSS='''*{box-sizing:border-box}:root{--bg:#0e1118;--c:#181d2a;--t:#e8ebf3;--m:#9aa3b8;--a:#7ee0c3;--b:#ffffff1c}@media(prefers-color-scheme:light){:root{--bg:#f6f7fb;--c:#fff;--t:#161a24;--m:#566;--a:#0a8f6e;--b:#0002}}body{margin:0;font:16px/1.7 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--t)}a{color:var(--a)}header,footer{display:flex;flex-wrap:wrap;gap:14px;align-items:center;justify-content:space-between;padding:16px 22px;border-bottom:1px solid var(--b)}footer{border:0;border-top:1px solid var(--b);margin-top:50px;color:var(--m);font-size:14px}.brand{font-weight:800;font-size:20px;text-decoration:none;color:var(--t)}nav a{margin-left:14px;text-decoration:none}main{max-width:860px;margin:0 auto;padding:30px 20px}h1{font-size:clamp(28px,5vw,42px);line-height:1.15}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:14px}.card{display:block;padding:18px;background:var(--c);border:1px solid var(--b);border-radius:14px;text-decoration:none;color:var(--t)}.card b{display:block}.card span{color:var(--m);font-size:14px}.box{background:var(--c);border:1px solid var(--b);border-radius:16px;padding:20px;margin:20px 0}label{display:block;font-weight:600;margin:12px 0 4px}input,select,textarea{width:100%;padding:10px;border-radius:10px;border:1px solid var(--b);background:var(--bg);color:var(--t);font:inherit}textarea{min-height:140px}button{margin-top:16px;padding:12px 22px;border:0;border-radius:10px;background:var(--a);color:#06100d;font-weight:700;font-size:16px;cursor:pointer}#out{white-space:pre-wrap;margin-top:16px}#out a{display:inline-block;margin:4px 8px 4px 0}.badge{display:inline-block;padding:4px 12px;border:1px solid var(--b);border-radius:99px;font-size:13px;color:var(--m)}.err{color:#ff6b6b}details{margin:8px 0}'''
JS=r'''(()=>{const T=window.T,$=s=>document.querySelector(s),f=$('#f'),out=$('#out');if(!f)return;
T.fields.forEach(([id,l,t,d,o])=>{let c;if(t==='select')c=`<select id="${id}">${o.map(x=>`<option value="${x[0]}"${x[0]==d?' selected':''}>${x[1]}</option>`).join('')}</select>`;else if(t==='textarea')c=`<textarea id="${id}"></textarea>`;else if(t==='file')c=`<input id="${id}" type="file" accept="image/*" multiple>`;else c=`<input id="${id}" type="${t}" value="${d}">`;f.insertAdjacentHTML('beforeend',`<label for="${id}">${l}</label>${c}`)});
f.insertAdjacentHTML('beforeend','<button type="submit">Run</button>');
const v=id=>($('#'+id)||{}).value,n=id=>+v(id),ext=t=>t==='image/png'?'png':t==='image/webp'?'webp':'jpg',nm=s=>s.replace(/\.[^.]+$/,'').replace(/[^\w-]+/g,'_');
const load=file=>new Promise((r,j)=>{const u=URL.createObjectURL(file),i=new Image();i.onload=()=>{URL.revokeObjectURL(u);r(i)};i.onerror=()=>j('Could not open '+file.name);i.src=u});
const cv=(i,w,h,cover)=>{const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,w,h);if(cover){const s=Math.max(w/i.width,h/i.height),sw=w/s,sh=h/s;x.drawImage(i,(i.width-sw)/2,(i.height-sh)/2,sw,sh,0,0,w,h)}else x.drawImage(i,0,0,w,h);return c};
const bl=(c,t,q)=>new Promise(r=>c.toBlob(r,t,q));
async function toKB(i,kb,w,h,exact){let s=1,b;for(let k=0;k<14;k++){const c=cv(i,Math.max(1,Math.round(w*s)),Math.max(1,Math.round(h*s)),exact);let lo=.05,hi=.95;b=await bl(c,'image/jpeg',lo);if(b.size>kb*1024&&!exact){s*=.85;continue}for(let j=0;j<7;j++){const m=(lo+hi)/2,t=await bl(c,'image/jpeg',m);if(t.size<=kb*1024){lo=m;b=t}else hi=m}return b}return b}
const link=(b,name)=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.textContent='Download '+name+' ('+(b.size/1024).toFixed(1)+' KB)';out.appendChild(a);return a};
const files=()=>[...($('#files')||{files:[]}).files];
async function mkpdf(it){const e=new TextEncoder(),P=[],O=[];let L=0;const add=d=>{const b=typeof d==='string'?e.encode(d):d;P.push(b);L+=b.length},o=(id,fn)=>{O[id]=L;add(id+' 0 obj\n');fn();add('\nendobj\n')},N=it.length;add('%PDF-1.4\n');o(1,()=>add('<</Type/Catalog/Pages 2 0 R>>'));o(2,()=>add('<</Type/Pages/Count '+N+'/Kids['+it.map((_,i)=>(3+3*i)+' 0 R').join(' ')+']>>'));it.forEach((m,i)=>{const p=3+3*i,s=`q ${m.w} 0 0 ${m.h} 0 0 cm /I Do Q`;o(p,()=>add(`<</Type/Page/Parent 2 0 R/MediaBox[0 0 ${m.w} ${m.h}]/Resources<</XObject<</I ${p+2} 0 R>>>>/Contents ${p+1} 0 R>>`));o(p+1,()=>add(`<</Length ${s.length}>>stream\n${s}\nendstream`));o(p+2,()=>{add(`<</Type/XObject/Subtype/Image/Width ${m.iw}/Height ${m.ih}/ColorSpace/DeviceRGB/BitsPerComponent 8/Filter/DCTDecode/Length ${m.b.length}>>stream\n`);add(m.b);add('\nendstream')})});const x=L;let t='xref\n0 '+(3*N+3)+'\n0000000000 65535 f \n';for(let i=1;i<3*N+3;i++)t+=String(O[i]).padStart(10,'0')+' 00000 n \n';add(t+'trailer\n<</Size '+(3*N+3)+'/Root 1 0 R>>\nstartxref\n'+x+'\n%%EOF');return new Blob(P,{type:'application/pdf'})}
const fmt=x=>x.toLocaleString('en-IN',{maximumFractionDigits:2});
const R={
async 'compress-image'(){for(const F of files()){const i=await load(F),b=await toKB(i,n('kb'),i.width,i.height);link(b,nm(F.name)+'_'+n('kb')+'kb.jpg');if(b.size>n('kb')*1024)out.append('\n(Could not reach the target; try a higher KB.)')}},
async 'resize-image'(){const t=v('fmt');for(const F of files()){const i=await load(F);let w=n('w'),h=n('h');if(v('keep')==='1'){const s=Math.min(w/i.width,h/i.height);w=Math.round(i.width*s);h=Math.round(i.height*s)}link(await bl(cv(i,w,h),t,.92),nm(F.name)+'_'+w+'x'+h+'.'+ext(t))}},
async 'convert-image'(){const t=v('fmt');for(const F of files()){const i=await load(F);link(await bl(cv(i,i.width,i.height),t,.92),nm(F.name)+'.'+ext(t))}},
async 'form-photo-resizer'(){for(const F of files()){const i=await load(F),b=await toKB(i,n('kb'),n('w'),n('h'),1);link(b,nm(F.name)+'_'+n('w')+'x'+n('h')+'.jpg');out.append('\n'+(b.size>n('kb')*1024?'Still above the limit: reduce width/height a little and retry.':'Within your size limit.'))}},
async 'images-to-pdf'(){const it=[];for(const F of files()){const i=await load(F),w=595,h=Math.round(595*i.height/i.width),c=cv(i,i.width,i.height),b=new Uint8Array(await(await bl(c,'image/jpeg',.9)).arrayBuffer());it.push({w,h,iw:i.width,ih:i.height,b})}if(!it.length)throw'Choose at least one image.';link(await mkpdf(it),'images.pdf')},
'word-counter'(){const t=v('text'),w=(t.match(/\S+/g)||[]).length;out.textContent=`Words: ${w}\nCharacters: ${t.length}\nCharacters (no spaces): ${t.replace(/\s/g,'').length}\nSentences: ${(t.match(/[^.!?]+[.!?]*/g)||[]).filter(s=>s.trim()).length}\nReading time: ${Math.max(w?1:0,Math.ceil(w/200))} min`},
'case-converter'(){const t=v('text'),m=v('mode');out.textContent=m==='upper'?t.toUpperCase():m==='lower'?t.toLowerCase():m==='title'?t.toLowerCase().replace(/(^|\s)(\S)/g,(a,b,c)=>b+c.toUpperCase()):t.toLowerCase().replace(/(^\s*\S|[.!?]\s+\S)/g,s=>s.toUpperCase())},
'emi-calculator'(){const P=n('p'),r=n('r')/1200,k=n('y')*12;if(!(P>0&&k>0))throw'Enter valid values.';const e=r?P*r*Math.pow(1+r,k)/(Math.pow(1+r,k)-1):P/k;out.textContent=`Monthly EMI: ${fmt(e)}\nTotal payment: ${fmt(e*k)}\nTotal interest: ${fmt(e*k-P)}`},
'sip-calculator'(){const M=n('m'),i=n('r')/1200,k=n('y')*12;if(!(M>0&&k>0))throw'Enter valid values.';const fv=i?M*((Math.pow(1+i,k)-1)/i)*(1+i):M*k;out.textContent=`Invested: ${fmt(M*k)}\nEstimated value: ${fmt(fv)}\nEstimated gain: ${fmt(fv-M*k)}\n\nAn illustration only. Returns are not guaranteed.`},
'gst-calculator'(){const a=n('a'),r=n('r')/100,add=v('mode')==='add',base=add?a:a/(1+r),g=base*r;out.textContent=`Price before GST: ${fmt(base)}\nGST amount: ${fmt(g)} (CGST ${fmt(g/2)} + SGST ${fmt(g/2)})\nPrice with GST: ${fmt(base+g)}`},
'age-calculator'(){const d=new Date(v('dob')),t=new Date();if(isNaN(d)||d>t)throw'Pick a valid past date.';let y=t.getFullYear()-d.getFullYear(),m=t.getMonth()-d.getMonth(),dd=t.getDate()-d.getDate();if(dd<0){m--;dd+=new Date(t.getFullYear(),t.getMonth(),0).getDate()}if(m<0){y--;m+=12}let nb=new Date(t.getFullYear(),d.getMonth(),d.getDate());if(nb<=t)nb.setFullYear(t.getFullYear()+1);out.textContent=`Age: ${y} years, ${m} months, ${dd} days\nTotal days lived: ${Math.floor((t-d)/864e5)}\nNext birthday in: ${Math.ceil((nb-t)/864e5)} days`},
'json-formatter'(){try{const j=JSON.parse(v('text'));out.textContent=JSON.stringify(j,null,v('mode')==='pretty'?2:0)}catch(e){throw'Invalid JSON: '+e.message}},
'password-generator'(){const s='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'+(v('sym')==='1'?'!@#$%^&*()-_=+[]{}?':''),L=Math.min(128,Math.max(6,n('len'))),a=new Uint32Array(L);crypto.getRandomValues(a);out.textContent=[...a].map(x=>s[x%s.length]).join('')},
'base64-tool'(){try{const t=v('text');out.textContent=v('mode')==='enc'?btoa(String.fromCharCode(...new TextEncoder().encode(t))):new TextDecoder().decode(Uint8Array.from(atob(t.trim()),c=>c.charCodeAt(0)))}catch(e){throw'Could not process: check your input.'}}};
f.addEventListener('submit',async e=>{e.preventDefault();out.innerHTML='';out.classList.remove('err');const b=f.querySelector('button');b.disabled=true;try{if(T.fields[0][2]==='file'&&!files().length)throw'Please choose a file first.';await R[document.body.dataset.tool]()}catch(x){out.classList.add('err');out.textContent=x.message||x}b.disabled=false})})();'''
JS=JS.replace('const R={','const R={'+EXT_JS,1).replace("x.fillStyle='#fff';x.fillRect(0,0,w,h);","if(!cv.t){x.fillStyle='#fff';x.fillRect(0,0,w,h)}").replace('await R[document.body.dataset.tool]()','cv.t=0;await R[T.e||document.body.dataset.tool]()').replace("async 'resize-image'(){const t=v('fmt');","async 'resize-image'(){const t=v('fmt');cv.t=t!=='image/jpeg';").replace("async 'convert-image'(){const t=v('fmt');","async 'convert-image'(){const t=v('fmt');cv.t=t!=='image/jpeg';").replace('GST amount: ${fmt(g)} (CGST ${fmt(g/2)} + SGST ${fmt(g/2)})','Tax amount: ${fmt(g)}${T.split?` (CGST ${fmt(g/2)} + SGST ${fmt(g/2)})`:""}').replace('Price before GST','Price before tax').replace('Price with GST','Price with tax')
