    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{BASE}{path}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta name="twitter:card" content="summary"><link rel="alternate" hreflang="en" href="{BASE}{path}"><link rel="alternate" hreflang="x-default" href="{BASE}{path}"><link rel="stylesheet" href="{p}assets/style.css">{extra}</head><body{' data-tool="'+path.split('/')[1]+'"' if path.startswith('tools/') else ''}><header><a class="brand" href="{p}index.html">meow<span style="color:var(--a)">tools</span></a><nav><a href="{p}index.html#tools">Tools</a><a href="{p}about/index.html">About</a><a href="{p}privacy-policy/index.html">Privacy</a></nav></header><main>{body}</main><footer><span>&copy; {D[:4]} MeowTools. Files are processed in your browser.</span><nav><a href="{p}about/index.html">About</a><a href="{p}privacy-policy/index.html">Privacy</a><a href="{p}terms/index.html">Terms</a><a href="{p}contact/index.html">Contact</a></nav></footer></body></html>'''
